void Campaigns::registerRoutes(httplib::Server& svr, std::shared_ptr<AuthenticationManager> auth)
{
    svr.Get("/ad_accounts/{ad_account_id}/pins/analytics", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdpinsanalyticsGetRequest(req, res, auth);
    });
    svr.Get("/ad_accounts/{ad_account_id}/campaigns/targeting_analytics", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdcampaignstargetingAnalyticsGetRequest(req, res, auth);
    });
    svr.Get("/ad_accounts/{ad_account_id}/campaigns/analytics", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdcampaignsanalyticsGetRequest(req, res, auth);
    });
    svr.Post("/ad_accounts/{ad_account_id}/campaigns", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdcampaignsPostRequest(req, res, auth);
    });
    svr.Get("/ad_accounts/{ad_account_id}/campaigns/{campaign_id}", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdcampaignscampaignIdGetRequest(req, res, auth);
    });
    svr.Get("/ad_accounts/{ad_account_id}/campaigns", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdcampaignsGetRequest(req, res, auth);
    });
    svr.Patch("/ad_accounts/{ad_account_id}/campaigns", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdcampaignsPatchRequest(req, res, auth);
    });
    svr.Post("/ad_accounts/{ad_account_id}/campaigns/delivery_estimates", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdcampaignsdeliveryEstimatesPostRequest(req, res, auth);
    });
}

